// universities.js — university & program data only (no page behaviour, no scoring)
//
// How it connects to the results:
//   calculateResults() (scoring.js) returns { major: "<majorId>", ... }
//     → the major's name comes from MAJORS (majors.js)          ← source of truth for names/ids
//     → its programs are the rows below with the same majorId
//
// ⚠️ NO REAL UNIVERSITY DATA YET — the university spreadsheet has not been imported.
// Only the 2 SAMPLE rows exist. They have isSample: true and are hidden on the real site.
// To see them while testing, add ?samples=1 to the address, e.g. index.html?samples=1
//
// Rules for unknown information:
//   null  → any unknown single value (text, number, date, url)
//   []    → an empty list (scholarships, typicalCareers, sourceNotes)
//   Never fill a gap with a guess.
//
// A row from your spreadsheet is NOT automatically verified:
//   verificationStatus: "unverified" | "partially_verified" | "verified"
//   lastVerified:       the real date someone checked the official source, or null


// ---------------------------------------------------------
// Extra information per major (description + possible careers).
// Names are NOT repeated here — they come from MAJORS in majors.js.
// Add an entry only when you have checked information:
//
//   "major-id": {
//     descriptionKm: "...",      // short, student-friendly Khmer description
//     typicalCareers: ["...", "..."]  // possible paths — a degree does not guarantee a career
//   },
// ---------------------------------------------------------
const MAJOR_DETAILS = {
};


// ---------------------------------------------------------
// One object per university PROGRAM (same as one row in the Google Sheet).
// Scholarship objects inside "scholarships" look like:
//   { name, nameKm, officialUrl, deadline, eligibility, coverage, lastVerified }
// A scholarship only counts as verified when it has officialUrl AND lastVerified.
// tuitionPeriod: "semester" | "year" | "total" | "other" | null (null = not confirmed)
// programType: e.g. "National Program", "International Program (IP)", "Dual Degree Program", or null.
//   The same program with different prices/requirements = separate rows, one per programType.
// notes: internal review notes (sheet row, spelling fixes, things to check) — NOT shown to students.
// ---------------------------------------------------------
